WITH micro AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','MS-5006606-4693892971CF47B4B2684C3A94950BEE','BA-2921401-9177991E4861442EACDDC06DB91','BA-2929057-C5D11EE026A64399A6EF36764E8739E9']) AS id_imovel),car AS (SELECT a.id_imovel,a.id_municipio FROM `basedosdados.br_sfb_sicar.area_imovel` a JOIN micro USING(id_imovel) WHERE a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY a.id_imovel ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT REPLACE(id_car,'-','') id_car_norm,id_referencia_bacen FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023),mut AS (SELECT DISTINCT id_referencia_bacen,cpf,cnpj FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao=2023),docs AS (SELECT DISTINCT COALESCE(NULLIF(m.cpf,''),NULLIF(m.cnpj,'')) documento,CASE WHEN m.cpf IS NOT NULL AND m.cpf!='' THEN 'CPF' ELSE 'CNPJ' END tipo_documento,c.id_municipio,p.id_referencia_bacen FROM p JOIN car c ON p.id_car_norm=REPLACE(c.id_imovel,'-','') JOIN mut m USING(id_referencia_bacen) WHERE COALESCE(NULLIF(m.cpf,''),NULLIF(m.cnpj,'')) IS NOT NULL),emb AS (SELECT cpf_cnpj_embargado,id_municipio,COUNT(*) embargos,MIN(data_embargo) primeiro_embargo,MAX(data_embargo) ultimo_embargo,ARRAY_AGG(DISTINCT id_embargo LIMIT 10) ids_embargos FROM `basedosdados.br_ibama_fiscalizacao.area_embargada` WHERE ano BETWEEN 1987 AND 2026 GROUP BY cpf_cnpj_embargado,id_municipio) SELECT d.documento,d.tipo_documento,d.id_municipio,d.id_referencia_bacen,COALESCE(e.embargos,0) embargos_no_mesmo_municipio,e.primeiro_embargo,e.ultimo_embargo,e.ids_embargos FROM docs d LEFT JOIN emb e ON e.cpf_cnpj_embargado=d.documento AND e.id_municipio=d.id_municipio ORDER BY d.documento,d.id_referencia_bacen